final class ForwardingProxy: NSProxy {
    let target: AnyObject
    override func forwardingTarget(for sel: Selector) -> Any? {
        target.responds(to: sel) ? target : super.forwardingTarget(for: sel)
    }
    override func responds(to sel: Selector) -> Bool {
        super.responds(to: sel) || target.responds(to: sel)
    }
}
